static void initializers_clear(struct em_initializers *members)
{
	neocc_string_clear(&members->state.string);
	members->state.global_expression = 0;
}

static int initializers_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	if (self->ref_count == 1)
		initializers_clear(self->members);
	return R_P;
}

static int initializers_close(struct object *self,
	const struct vr *caller_context)
{
	struct em_initializers *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		initializers_clear(members);
	return R_P;
}

static int initializers_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_initializers *members = self->members;

	if (action != NEOCC_AC0_INITIALIZERS_RESET) {
		SBO_OBJECT_INTERACT0;
	}

	if (!self->ref_count)
		return RN_INVALIDARG;
	initializers_clear(members);
	return R_P;
}

