void tog_initializers(struct object *object)
{
	object->open = initializers_open;
	object->input = initializers_input;
	object->output = initializers_output;
	object->io_put = initializers_io_put;
	object->interact0 = initializers_interact0;
	object->interact1 = initializers_interact1;
	object->interact2 = initializers_interact2;
	object->interact3 = initializers_interact3;
	object->close = initializers_close;
}
